arguments.command:
cd /filesystem && mkdir -p /tmp/txt && for f in $(find . -type f \( -name "*.pdf" \)); do out="/tmp/txt/$(echo $f | sed 's|^\./||; s|/|__|g').txt"; pdftotext -layout "$f" "$out"; done; for f in $(find . -type f -name "*.docx"); do out="/tmp/txt/$(echo $f | sed 's|^\./||; s|/|__|g').txt"; pandoc "$f" -t plain -o "$out" 2>/dev/null; done; for f in $(find . -type f -name "*.eml"); do out="/tmp/txt/$(echo $f | sed 's|^\./||; s|/|__|g').txt"; cp "$f" "$out"; done; python3 << 'EOF'
import openpyxl, glob, os
for f in glob.glob('/filesystem/**/*.xlsx', recursive=True):
    out = '/tmp/txt/' + os.path.relpath(f, '/filesystem').replace('/','__') + '.txt'
    if 'AMI_Interval' in f:
        continue
    wb = openpyxl.load_workbook(f)
    with open(out,'w') as fh:
        for ws in wb.worksheets:
            fh.write(f'### SHEET {ws.title} [{ws.sheet_state}] {ws.dimensions}\n')
            for r in ws.iter_rows(values_only=True):
                if any(c is not None for c in r):
                    fh.write(' | '.join('' if c is None else str(c) for c in r) + '\n')
EOF
ls -la /tmp/txt | head -80; grep -il "bramwick" /tmp/txt/*; echo ---; grep -il "ALN-214" /tmp/txt/*
